function fbo_symbol_svg(int $index): string
{
    if (!isset(FBO_PIXEL_SYMBOLS[$index])) return '';
    $rows = FBO_PIXEL_SYMBOLS[$index];
    $width = max(array_map('strlen', $rows));
    $xOffset = (16 - $width) / 2;
    $yOffset = $index === 0 ? 1 : floor((16 - count($rows)) / 2);
    $path = '';
    foreach ($rows as $y => $row) {
        for ($x = 0; $x < strlen($row); $x++) {
            if ($row[$x] === '#') $path .= 'M' . ($x + $xOffset) . ' ' . ($y + $yOffset) . 'h1v1h-1z';
        }
    }
    $legs = $index === 0 ? '<g class="visitor-horse-legs-a"><path d="M4 9h2v4H5v2H3v-1h1zM10 9h2v4h1v2h-2v-2h-1z"/></g><g class="visitor-horse-legs-b"><path d="M4 9h2v2H4v2H2v-1h1v-2h1zM10 9h2v2h2v2h1v1h-2v-2h-2v-1h-1z"/></g>' : '';
    $motions = ['gallop', 'music', 'twinkle', 'flash', 'sway', 'spin', 'music', 'shake', 'float', 'float', 'nod', 'sway', 'beat', 'flutter', 'sway', 'spin', 'spin', 'launch', 'nod', 'burn', 'grow', 'shake', 'music', 'sway'];
    return '<svg class="visitor-pixel-symbol" data-motion="' . $motions[$index] . '" width="28" height="28" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" aria-hidden="true" focusable="false" fill="#000000" shape-rendering="crispEdges"><path d="' . $path . '"/>' . $legs . '</svg>';
}
